  const concurrent=await Promise.all([1,2].map(()=>resource(a,"tables",{name:"طاولة 9",branchId:a.branch,status:"available",data:{sectionId:family,number:9,capacity:4}})));assert.equal(concurrent.filter(r=>r.status===201).length,1);assert.equal(concurrent.filter(r=>r.body.code==="TABLE_NUMBER_EXISTS").length,1);
